"  /* --- ML-KEM encapsulate/decapsulate (FIPS 203) --------------\n"
"     New SubtleCrypto methods.  encapsulateBits derives a shared key\n"
"     and a ciphertext from a recipient's public key.  decapsulateBits\n"
"     recovers the shared key from the ciphertext using the matching\n"
"     private key.  *Key variants wrap the shared secret into a fresh\n"
"     CryptoKey of the caller-supplied algorithm. */\n"
"  function _mlkemNames() { return {'ML-KEM-512':1, 'ML-KEM-768':1, 'ML-KEM-1024':1}; }\n"
"  SubtleCrypto.prototype.encapsulateBits = function (algorithm, encapsulationKey) {\n"
"    try {\n"
"      var alg = _normAlg(algorithm);\n"
"      if (!_mlkemNames()[alg.name])\n"
"        throw _notSupported('encapsulateBits: unsupported algorithm ' + alg.name);\n"
"      if (!(encapsulationKey instanceof CryptoKey))\n"
"        throw _typeErr('encapsulateBits: encapsulationKey must be a CryptoKey');\n"
"      if (encapsulationKey.algorithm.name !== alg.name)\n"
"        throw _invalidAccess(alg.name + ': encapsulationKey algorithm mismatch');\n"
"      if (encapsulationKey.type !== 'public')\n"
"        throw _invalidAccess('encapsulateBits: encapsulationKey.type must be public');\n"
"      _requireUsage(encapsulationKey, 'encapsulateBits');\n"
"      var mat = _unbox(encapsulationKey);\n"
"      var out = rc.mlkem_encapsulate(mat.pem);\n"
"      return Promise.resolve({\n"
"        sharedKey:  _toAB(out.sharedSecret),\n"
"        ciphertext: _toAB(out.ciphertext)\n"
"      });\n"
"    } catch (e) { return Promise.reject(e); }\n"
"  };\n"
"  SubtleCrypto.prototype.decapsulateBits = function (algorithm, decapsulationKey, ciphertext) {\n"
"    try {\n"
"      var alg = _normAlg(algorithm);\n"
"      if (!_mlkemNames()[alg.name])\n"
"        throw _notSupported('decapsulateBits: unsupported algorithm ' + alg.name);\n"
"      if (!(decapsulationKey instanceof CryptoKey))\n"
"        throw _typeErr('decapsulateBits: decapsulationKey must be a CryptoKey');\n"
"      if (decapsulationKey.algorithm.name !== alg.name)\n"
"        throw _invalidAccess(alg.name + ': decapsulationKey algorithm mismatch');\n"
"      if (decapsulationKey.type !== 'private')\n"
"        throw _invalidAccess('decapsulateBits: decapsulationKey.type must be private');\n"
"      _requireUsage(decapsulationKey, 'decapsulateBits');\n"
"      var dmat = _unbox(decapsulationKey);\n"
"      var shared = rc.mlkem_decapsulate(_toBuf(ciphertext), dmat.pem);\n"
"      return Promise.resolve(_toAB(shared));\n"
"    } catch (e) { return Promise.reject(e); }\n"
"  };\n"
"  /* *Key variants wrap the shared secret into a CryptoKey of the\n"
"     specified sharedKeyAlgorithm (typically AES-* or HMAC). */\n"
"  SubtleCrypto.prototype.encapsulateKey = function (algorithm, encapsulationKey,\n"
"                                                     sharedKeyAlgorithm,\n"
"                                                     extractable, keyUsages) {\n"
"    var self = this;\n"
"    try {\n"
"      var alg = _normAlg(algorithm);\n"
"      _requireUsage(encapsulationKey, 'encapsulateKey');\n"
"      if (encapsulationKey.type !== 'public')\n"
"        throw _invalidAccess('encapsulateKey: encapsulationKey.type must be public');\n"
"      var mat = _unbox(encapsulationKey);\n"
"      var out = rc.mlkem_encapsulate(mat.pem);\n"
"      var sharedBuf = Buffer.isBuffer(out.sharedSecret) ? out.sharedSecret\n"
"                       : Buffer.from(out.sharedSecret);\n"
"      return self.importKey('raw', sharedBuf, sharedKeyAlgorithm,\n"
"                             extractable, keyUsages).then(function (sk) {\n"
"        return {sharedKey: sk, ciphertext: _toAB(out.ciphertext)};\n"
"      });\n"
"    } catch (e) { return Promise.reject(e); }\n"
"  };\n"
"  SubtleCrypto.prototype.decapsulateKey = function (algorithm, decapsulationKey,\n"
"                                                     ciphertext, sharedKeyAlgorithm,\n"
"                                                     extractable, keyUsages) {\n"
"    var self = this;\n"
"    try {\n"
"      _requireUsage(decapsulationKey, 'decapsulateKey');\n"
"      if (decapsulationKey.type !== 'private')\n"
"        throw _invalidAccess('decapsulateKey: decapsulationKey.type must be private');\n"
"      var dmat = _unbox(decapsulationKey);\n"
"      var shared = rc.mlkem_decapsulate(_toBuf(ciphertext), dmat.pem);\n"
"      var sBuf = Buffer.isBuffer(shared) ? shared : Buffer.from(shared);\n"
"      return self.importKey('raw', sBuf, sharedKeyAlgorithm,\n"
"                            extractable, keyUsages);\n"
"    } catch (e) { return Promise.reject(e); }\n"
"  };\n"
"\n"
"  /* --- Crypto -------------------------------------------------\n"
"     Top-level object: subtle + getRandomValues + randomUUID. */\n"
"  function Crypto() {\n"
"    if (!(this instanceof Crypto)) return new Crypto();\n"
"  }\n"
"  if (typeof Symbol !== 'undefined' && Symbol.toStringTag) {\n"
"    Object.defineProperty(Crypto.prototype, Symbol.toStringTag, {\n"
"      value: 'Crypto', configurable: true\n"
"    });\n"
"  }\n"
"  /* getRandomValues(typedArray) — fills the array in place and\n"
"     returns it.  Throws TypeMismatchError on float/DataView/non-\n"
"     TypedArray (per Web Crypto §4.2 — only integer typed arrays\n"
"     allowed).  Throws QuotaExceededError if length > 65536. */\n"
"  var _INT_TA_NAMES = {Int8Array:1, Uint8Array:1, Uint8ClampedArray:1,\n"
"                       Int16Array:1, Uint16Array:1,\n"
"                       Int32Array:1, Uint32Array:1,\n"
"                       BigInt64Array:1, BigUint64Array:1};\n"
"  Crypto.prototype.getRandomValues = function (typedArray) {\n"
"    if (typedArray == null || typeof typedArray !== 'object'\n"
"        || typedArray instanceof DataView)\n"
"      throw _domEx('TypeMismatchError',\n"
"        'getRandomValues: argument must be an integer TypedArray');\n"
"    var tag = typedArray.constructor && typedArray.constructor.name;\n"
"    if (!tag || !_INT_TA_NAMES[tag])\n"
"      throw _domEx('TypeMismatchError',\n"
"        'getRandomValues: argument must be an integer TypedArray (got ' + (tag||typeof typedArray) + ')');\n"
"    if (typedArray.byteLength > 65536) {\n"
"      var e = _domEx('QuotaExceededError',\n"
"        'getRandomValues: byteLength must be <= 65536');\n"
"      throw e;\n"
"    }\n"
"    var bytes = rc.rand(typedArray.byteLength);\n"
"    var u8    = new Uint8Array(typedArray.buffer, typedArray.byteOffset, typedArray.byteLength);\n"
"    for (var i = 0; i < bytes.length; i++) u8[i] = bytes[i];\n"
"    return typedArray;\n"
"  };\n"
"  /* randomUUID() — v4 UUID string.  Delegate to the same source\n"
"     of randomness; format per RFC 4122 §4.4. */\n"
"  Crypto.prototype.randomUUID = function () {\n"
"    var b = rc.rand(16);\n"
"    /* Set version (4) and variant (10xx) bits. */\n"
"    b[6] = (b[6] & 0x0f) | 0x40;\n"
"    b[8] = (b[8] & 0x3f) | 0x80;\n"
"    function h(i, n) {\n"
"      var s = '';\n"
"      for (var j = 0; j < n; j++) {\n"
"        var v = b[i+j];\n"
"        s += (v < 16 ? '0' : '') + v.toString(16);\n"
"      }\n"
"      return s;\n"
"    }\n"
"    return h(0,4) + '-' + h(4,2) + '-' + h(6,2) + '-' + h(8,2) + '-' + h(10,6);\n"
"  };\n"
"\n"
"  /* Singleton instance — like globalThis.crypto in node. */\n"
"  var crypto = new Crypto();\n"
"  Object.defineProperty(crypto, 'subtle', {\n"
"    value: new SubtleCrypto(), enumerable: true, configurable: false, writable: false\n"
"  });\n"
"\n"
"  /* Expose the CryptoKey class as an instanceof target.  Spec says\n"
"     direct construction is forbidden but `key instanceof CryptoKey`\n"
"     must hold for keys returned by subtle methods. */\n"
"  return {\n"
"    Crypto:        Crypto,\n"
"    SubtleCrypto:  SubtleCrypto,\n"
"    CryptoKey:     CryptoKey,\n"
"    crypto:        crypto    /* the singleton — `require('crypto').webcrypto` returns this */\n"
"  };\n"
"}";
/* duk_open_module: the entry point require('rampart-whatwg') hits. */
duk_ret_t duk_open_module(duk_context *ctx)
{
    /* 1. Install Blob and File (native C — see rampart-blob.c). */
    duk_rp_blob_init(ctx);

    /* 2. Build the Web Crypto singleton and install it as
          globalThis.crypto.  Done BEFORE the install JS so subsequent
          steps (and nodeshim's require('crypto').webcrypto getter)
          see the global.  The webcrypto_js IIFE returns
          {Crypto, SubtleCrypto, CryptoKey, crypto} — we pluck the
          singleton, defineProperty it as globalThis.crypto with
          {writable, configurable} so user code can still shadow if
          needed, and discard the rest (constructors live on the
          singleton's prototype chain). */
    duk_push_string(ctx, "rampart-whatwg.c:webcrypto_js");
    duk_compile_string_filename(ctx, DUK_COMPILE_FUNCTION, webcrypto_js);
    duk_call(ctx, 0);                          /* [webcrypto_exports] */
    duk_get_prop_string(ctx, -1, "crypto");    /* [exports, crypto_singleton] */
    duk_push_global_object(ctx);               /* [exports, singleton, global] */
    duk_dup(ctx, -2);                          /* [exports, singleton, global, singleton] */
    /* Use defineProperty so the lazy getter on globalThis.crypto
       (installed by register.c) is overwritten cleanly. */
    duk_eval_string(ctx,
        "(function(g, v) {\n"
        "  Object.defineProperty(g, 'crypto', {\n"
        "    value: v, writable: true, configurable: true, enumerable: false\n"
        "  });\n"
        "})");                                 /* [exports, singleton, global, singleton, fn] */
    duk_insert(ctx, -3);                       /* [exports, singleton, fn, global, singleton] */
    duk_call(ctx, 2);                          /* [exports, singleton, undef] */
    duk_pop_2(ctx);                            /* [exports] */
    /* Also expose Crypto, SubtleCrypto, CryptoKey constructors as
       globals (Web Crypto API: instanceof targets).  exports is the
       webcrypto IIFE result; pluck from there. */
    duk_get_prop_string(ctx, -1, "Crypto");
    duk_put_global_string(ctx, "Crypto");
    duk_get_prop_string(ctx, -1, "SubtleCrypto");
    duk_put_global_string(ctx, "SubtleCrypto");
    duk_get_prop_string(ctx, -1, "CryptoKey");
    duk_put_global_string(ctx, "CryptoKey");
    duk_pop(ctx);                              /* pop exports */

    /* 3a. Load the WHATWG Streams polyfill (vendored from
           web-streams-polyfill v4.3.0, MIT).  UMD bundle side-effects
           globalThis.WebStreamsPolyfill with the 13 stream classes.
           The install JS below moves them onto globalThis individually
           via _set() and cleans up WebStreamsPolyfill. */
    duk_push_string(ctx, "rampart-whatwg.c:web-streams-polyfill");
    if (duk_pcompile_string_filename(ctx, DUK_COMPILE_EVAL, web_streams_polyfill_js) != 0
        || duk_pcall(ctx, 0) != 0) {
        (void)duk_throw(ctx);
    }
    duk_pop(ctx);  /* discard UMD eval result (it's the exports obj) */

    /* 3. Run the JS install block which defines URL/URLSearchParams,
          MessagePort/MessageChannel/BroadcastChannel, Event/EventTarget/
          AbortController/DOMException/atob/btoa/structuredClone/
          queueMicrotask/reportError/navigator/WebSocket, and augments
          performance.  whatwg is standalone — does NOT require nodeshim;
          the platform string for navigator.platform is the only piece
          of host info needed and we pass it from C. */
    duk_push_string(ctx, "rampart-whatwg.c:install");
    if (duk_pcompile_string_filename(ctx, DUK_COMPILE_EVAL, whatwg_install_js) != 0) {
        (void)duk_throw(ctx);
    }
    /* DUK_COMPILE_EVAL gives us a program function; running it (with
       zero args) returns the value of the program expression — which
       is the (function (rampartPlatform) { ... }) function itself. */
    if (duk_pcall(ctx, 0) != 0) {
        (void)duk_throw(ctx);
    }
    /* Stack: [install_fn].  Push platform string + zlib-stream
       helper functions and call.  The zlib helpers stay private to
       the install JS closure scope — never exposed as public API. */
    /* navigator.platform per WHATWG/HTML spec.  Apple and Microsoft both
       intentionally lie about architecture for compat ("MacIntel" even on
       Apple Silicon Macs, "Win32" even on 64-bit Windows) — match the
       browsers' behavior on those.  Everything else gets real sysname +
       machine via uname() so ARM/aarch64/riscv hosts report accurately
       instead of being mislabeled "x86_64". */
#if defined(__APPLE__)
    duk_push_string(ctx, "MacIntel");
#elif defined(_WIN32)
    duk_push_string(ctx, "Win32");
#else
    {
        /* utsname field sizes vary (Linux 65, glibc-GNU-ext 257).  Use
           printf precision to bound each field to 30 chars — real values
           are short ("Linux"/"FreeBSD"/"Darwin", "x86_64"/"aarch64") so
           truncation is harmless and keeps the buffer compact. */
        struct utsname _u;
        char _platbuf[80];
        if (uname(&_u) == 0)
            snprintf(_platbuf, sizeof _platbuf, "%.30s %.30s", _u.sysname, _u.machine);
        else
            snprintf(_platbuf, sizeof _platbuf, "unknown");
        duk_push_string(ctx, _platbuf);
    }
#endif
    duk_push_c_function(ctx, rp_zs_init,   3);
    duk_push_c_function(ctx, rp_zs_push,   2);
    duk_push_c_function(ctx, rp_zs_finish, 1);
    if (duk_pcall(ctx, 4) != 0) {
        (void)duk_throw(ctx);
    }
    duk_pop(ctx);  /* discard the (void) call result */

    /* 4. Module exports object.  The side effect (globals installed)
          is the real product; the exports just hand back a marker so
          users can `var w = require('rampart-whatwg')` for ergonomics. */
    duk_push_object(ctx);
    duk_push_true(ctx);
    duk_put_prop_string(ctx, -2, "loaded");
    return 1;
}
